{"path": "~/kalari-showcase-ref/runs/b78203f0edee/workspace/disbursement_sync.py", "content": """"Copy every disbursement from the Meridian Disbursements API into disbursements.jsonl."""
import argparse
import json
import urllib.parse
import urllib.request


def _get_json(url):
    with urllib.request.urlopen(url, timeout=30) as resp:
        return json.load(resp)


def fetch_disbursements(base_url):
    """Export every disbursement, following the v2 cursor until the export drains.

    Windows overlap: the disbursement that closes one window is repeated at the
    start of the next. That repeated record is delivered first at its
    window-edge version and again, at the start of the next window, at its
    final version. Keep the last delivery per id so the final version wins.
    """
    disbursements = {}
    cursor = None
    while True:
        params = {"limit": 100}
        if cursor is not None:
            params["cursor"] = cursor
        url = f"{base_url}/v2/disbursements?{urllib.parse.urlencode(params)}"
        payload = _get_json(url)
        for d in payload["disbursements"]:
            disbursements[d["id"]] = d
        if payload["drained"]:
            return list(disbursements.values())
        cursor = payload["cursor"]


def verify_disbursements(base_url, disbursements):
    """Ask the server whether the export captured every id exactly once."""
    body = json.dumps({"disbursements": disbursements}).encode()
    request = urllib.request.Request(
        f"{base_url}/v2/verify",
        data=body,
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    with urllib.request.urlopen(request, timeout=30) as resp:
        return json.load(resp)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--base-url", required=True)
    ap.add_argument("--out", default="disbursements.jsonl")
    args = ap.parse_args()
    base_url = args.base_url.rstrip("/")
    disbursements = fetch_disbursements(base_url)
    with open(args.out, "w") as f:
        for d in disbursements:
            f.write(json.dumps(d) + "\n")

    result = verify_disbursements(base_url, disbursements)
    print(f"synced {len(disbursements)} disbursements")
    print(
        "verified: "
        f"expected={result['ids_expected']} seen={result['ids_seen']} "
        f"missing={result['missing']} extra={result['extra']} "
        f"duplicates={result['duplicates']} each_once={result['each_once']}"
    )
    if not result["each_once"]:
        raise SystemExit("verification failed: export is not exactly once")


if __name__ == "__main__":
    main()
"}

